   USE mpi, only: MPI_SCATTER
   USE mpi, only: MPI_ISCATTER

!  MPI Send and receives   
   USE mpi, only: MPI_SEND
   USE mpi, only: MPI_RECV
   USE mpi, only: MPI_ISEND
   USE mpi, only: MPI_IRECV
   USE mpi, only: MPI_SSEND
   USE mpi, only: MPI_ISSEND
   USE mpi, only: MPI_SENDRECV
   USE mpi, only: MPI_WIN_CREATE
   USE mpi, only: MPI_WIN_CREATE_DYNAMIC
   USE mpi, only: MPI_WIN_ALLOCATE
   USE mpi, only: MPI_WIN_ALLOCATE_SHARED
   USE mpi, only: MPI_WIN_FREE
   USE mpi, only: MPI_WIN_LOCK
   USE mpi, only: MPI_WIN_UNLOCK
   USE mpi, only: MPI_LOCK_EXCLUSIVE
   USE mpi, only: MPI_LOCK_SHARED
   USE mpi, only: MPI_PUT
   USE mpi, only: MPI_GET
   USE mpi, only: MPI_ACCUMULATE
   USE mpi, only: MPI_FETCH_AND_OP
   USE mpi, only: MPI_GET_ACCUMULATE

!  MPI Characteristics  
   USE mpi, only: MPI_WTICK
   USE mpi, only: MPI_WTIME

   ! MPI status functions
   USE mpi, only: MPI_TESTANY
   USE mpi, only: MPI_TESTALL

   ! Barrier functions
   USE mpi, only: MPI_IBARRIER
   USE mpi, only: MPI_WAITANY
   USE mpi, only: MPI_WAITSOME
#endif
#endif

#ifdef INTEL_ifort
   USE ifport, only: flush
#endif

#ifdef SERVICE_ROUTINES
   USE service_routines, only: flush
#endif

#ifdef F90_UNIX_IO
   USE f90_unix_io, only: flush
#endif

   implicit none

   include "system.int"


   ! Tonto system variables
   type(SYSTEM_TYPE), allocatable, public :: tonto

contains

!  ==========
!  Allocation
!  ==========

   subroutine create(self)
   ! Allocate the system object
      type(SYSTEM_TYPE), allocatable, OUT :: self
      allocate(self)
      call initialize_(self)
   end subroutine

   subroutine destroy(self)
   !  Destroy the memory manager object
      type(SYSTEM_TYPE), allocatable, INOUT :: self
      if (NOT allocated(self)) return
      call finalize_(self)
      deallocate(self)
   end subroutine


!  ===========
!  Set methods
!  ===========

   PURE subroutine set_defaults(self)
   !  Set defaults
      type(SYSTEM_TYPE), INOUT :: self
      self%error_status = 0
      self%warnings_issued = FALSE
      self%std_err_unit = TEXTFILE_STD_ERR_UNIT
      self%stdout_unit = TEXTFILE_STD_OUT_UNIT
      self%keyword_echo = FALSE

      ! Shell command slot, inherited from SYSTEM_COMMAND
      call set_command_defaults_(self)
   end subroutine

   subroutine initialize(self)
   ! Initialise the system object and set defaults
   ! Set the random seed from the date
      type(SYSTEM_TYPE), INOUT :: self
      call set_defaults_(self)
      ! MUST come before the seed: initialize_cloned_random_seed asks
      ! .is_master_processor, and until parallel_initialize runs, master_rank and
      ! processor_rank are both still DEFAULT(0) -- so EVERY rank believes it is
      ! master and seeds itself from its own clock. See below.
      call parallel_initialize_(self)
      call initialize_cloned_random_seed_(self)
   end subroutine

   subroutine initialize_cloned_random_seed(self)
   ! Initialise the random seed. Only for master and broadcast it
   ! so that all processors get the same random numbers.
      type(SYSTEM_TYPE), IN :: self
      VEC(INT,:), allocatable :: seed
      VEC(INT,8) :: dt
      INT :: n,i,t

      ! Get the size "n".
      ! ALL ranks, not just master: random_seed(size=) reports a property of the
      ! compiled RNG, so it is identical everywhere and never needed broadcasting.
      ! It used to be fetched under `if (.is_master_processor)` with the broadcast
      ! INSIDE that guard -- a collective no worker would ever reach, and `n` left
      ! undefined on workers at the allocate below. Calling it everywhere removes
      ! the collective rather than fixing it.
      call random_seed(size=n)

      ! Allocate seed array
      allocate(seed(n))

      ! Get random number seed
      if (is_master_processor_(self)) then

         ! Try system time for seed
         call system_clock(count=t)

         ! In case above does not work ...
         if (t==0) then
            call date_and_time(values=dt)
            t = dt(3)*24*60*60*60*1000+dt(5)*60*60*1000+dt(6)*60*1000+dt(7)*1000+dt(8)
         end if

         ! Set seed array
         i = 0
         seed = t+37*[(i,i = 0,n-1)]
      end if

      ! Broadcast the seed OUTSIDE the master guard, so every rank reaches this
      ! collective. It used to sit inside the `if (.is_master_processor)` block
      ! above, i.e. a broadcast only the root ever called.
      PARALLEL_BROADCAST(seed,master_processor_(tonto))

      ! Get the random numbers from same seed
      ! NOTE: cloned for each processor -- which is now actually true.
      call random_seed(put=seed)

      ! Clean
      deallocate(seed)
   end subroutine

   subroutine finalize(self)
   !  Finalise the system object
      type(SYSTEM_TYPE), INOUT :: self
      call parallel_finalize_(self)
   end subroutine


!  ================
!  Error operations
!  ================

   pure subroutine set_std_err_unit(self,n)
   ! Set the error unit number "n"
      type(SYSTEM_TYPE), INOUT :: self
      INT, IN :: n
      self%std_err_unit = n
   end subroutine

   pure subroutine set_std_err_file(self,file)
   ! Set the error output file to "file"
      type(SYSTEM_TYPE), INOUT :: self
      type(TEXTFILE_TYPE), IN :: file
      self%std_err_unit = file%unit
   end subroutine

   pure subroutine set_stdout_unit(self,n)
   ! Set the output unit number "n"
      type(SYSTEM_TYPE), INOUT :: self
      INT, IN :: n
      self%stdout_unit = n
   end subroutine

   pure subroutine set_stdout_file(self,file)
   ! Set the output file to "file"
      type(SYSTEM_TYPE), INOUT :: self
      type(TEXTFILE_TYPE), IN :: file
      self%stdout_unit = file%unit
   end subroutine

   pure subroutine set_keyword_echo(self,val)
   ! Set whether to echo user-input keywords
      type(SYSTEM_TYPE), INOUT :: self
      BIN, IN :: val
      self%keyword_echo = val
   end subroutine

   pure subroutine set_low_verbosity(self,val)
   ! Set whether a low level of output wanted. Whatever that means.
      type(SYSTEM_TYPE), INOUT :: self
      BIN, IN :: val
      self%low_verbosity = val
   end subroutine

   pure subroutine set_io_file_info(self,name,record,line,cursor)
   ! Record where the file being read had got to, for a later error message.
   ! Copied by value on purpose: a pointer to the file would outlive it. See
   ! .report_io_file_info.
      type(SYSTEM_TYPE), INOUT :: self
      STR(len=*), IN :: name
      INT, IN :: record
      STR(len=*), IN :: line
      INT, IN :: cursor
      self%io_file_name = name
      self%io_file_record = record
      self%io_file_line = line
      self%io_file_cursor = cursor
   end subroutine

   pure subroutine set_io_file_cursor(self,cursor)
   ! Record how far along the current line the parser has got. Separate from
   ! .set_io_file_info because the cursor moves item by item, long after the
   ! line was read -- see TEXTFILE:update_IO_cursor.
      type(SYSTEM_TYPE), INOUT :: self
      INT, IN :: cursor
      self%io_file_cursor = cursor
   end subroutine

   pure subroutine clear_io_file_info(self)
   ! Forget the file being read; called when one is closed.
      type(SYSTEM_TYPE), INOUT :: self
      self%io_file_name = " "
      self%io_file_record = 0
      self%io_file_line = " "
      self%io_file_cursor = 0
   end subroutine

   pure subroutine set_per_rank_IO_allowed(self,val)
   ! Set whether every rank may do its own I/O, instead of the master alone.
   ! Used where the ranks deliberately work on different data and so must
   ! open, write and close their OWN files -- see MOLECULE.SCF:fragment_SCF_para.
   ! NOTE: until 2026-08-03 this assigned .keyword_echo, so the flag could not
   ! be set at all and the escape hatch in SYSTEM:IO_is_allowed was dead code.
      type(SYSTEM_TYPE), INOUT :: self
      BIN, IN :: val
      self%per_rank_IO_allowed = val
   end subroutine


!  ==============
!  Error messages
!  ==============

   subroutine die(self,message)
   ! Set the error flag to 1 and terminate the program with a message
      type(SYSTEM_TYPE), INOUT :: self
      STR(len=*), IN :: message
      BIN :: stdout_open
      self%error_status = 1
      if (IO_is_allowed_(self)) then
         write(self%std_err_unit,*)
         write(self%std_err_unit,"(a)") "Error in "//trim(message)  ! message should include the routine name via foo
         inquire(unit=self%stdout_unit,opened=stdout_open)
         if (stdout_open) then
            if (self%std_err_unit/=self%stdout_unit) then
               write(self%stdout_unit,*)
               write(self%stdout_unit,"(a)") "Error in "//trim(message)  ! message should include the routine name via foo
            end if
         end if
      end if
      call report_io_file_info_(self)
      call report_keyword_info_(self)
#ifdef MPI
      ! MPI_ABORT, not MPI_FINALIZE. This is the ERROR path: one rank is dying and
      ! the others are still running. MPI_FINALIZE is COLLECTIVE -- every rank must
      ! call it -- so a single rank finalising here blocks while its peers carry on,
      ! and the job HANGS instead of failing. A hang is the least informative failure
      ! there is: no message, no exit code, no clue which rank died.
      !
      ! MPI_ABORT is unilateral by design: it terminates every rank in the
      ! communicator. Guarded on .is_parallel so a serial build (where MPI was never
      ! initialised) falls straight through to the stop below.
      !
      ! NOTE the previously commented-out line here passed .mpi_status (a
      ! VEC{INT}(MPI_STATUS_SIZE)) as MPI_ABORT's integer "ierror" argument -- it
      ! would not have compiled, and MPI_ABORT was never imported either. Both fixed.
      if (self%is_parallel) then

         ! Say WHY, on THIS rank, before the job is killed.
         !
         ! Everything above is gated on .IO_is_allowed, i.e. master only -- so
         ! when a NON-master rank dies, which is the usual case for an MPI-only
         ! bug, the message was never written at all and the job died in total
         ! silence: nothing on stdout, nothing on stderr, nothing in <job>.err.
         ! That makes a parallel failure nearly undiagnosable, and it cost most
         ! of a day on the hart MPI_ERR_TRUNCATE hunt.
         !
         ! Written straight to Fortran's preconnected stderr (unit 0), not via
         ! TEXTFILE and not to .std_err_unit:
         !   . unit 0 exists on EVERY rank, whereas the std_err file is opened
         !     only on the master and its unit number is merely broadcast;
         !   . TEXTFILE:flush contains PARALLEL_BROADCASTs, so flushing here --
         !     from the one rank that is dying, while its peers run on -- would
         !     be a collective entered by a single rank, i.e. a hang. The error
         !     path must not use collectives.
         ! The rank is included because "which rank died" is the first question.
         write(0,'(a,i0,a)') "Error on rank ",self%processor_rank,": "//trim(message)
         flush(0)
         call MPI_ABORT(MPI_COMM_WORLD,self%error_status,self%mpi_error)
      end if
#endif

      ! Show the calls that led here
#ifdef DEBUG
#ifdef __GFORTRAN__
      call backtrace
#endif
#endif

      ! Non-zero: .error_status was set to 1 above, and a caller -- a shell,
      ! a CI job, scripts/test.py -- can only see that through the exit code.
      ! A bare "stop" exits 0, i.e. reports success while dying.
      stop 1
   end subroutine

   subroutine die_if(self,condition,message)
   ! Set the error flag to 1 and terminate the program with a message
   ! provided "condition" is TRUE
      type(SYSTEM_TYPE), INOUT :: self
      BIN, IN :: condition
      STR(len=*), IN :: message
      if (condition) call die_(self,message)
   end subroutine

   subroutine warn(self,message,iostat)
   ! Set the error flag to -1 and issue a warning message.
      type(SYSTEM_TYPE), INOUT :: self
      STR(len=*) :: message
      INT, IN, optional :: iostat
      BIN :: stdout_open
      self%error_status = -1
      if (IO_is_allowed_(self)) then
         write(self%std_err_unit,"(' ')")
         write(self%std_err_unit,"(a)") "Warning from "//trim(message)  ! message should include the routine name
         if (self%std_err_unit/=self%stdout_unit) then
            write(self%stdout_unit,"(' ')")
            write(self%stdout_unit,"(a)") "Warning from "//trim(message)  ! message should include the routine name
         end if
      end if
      if (present(iostat)) then
         if (IO_is_allowed_(self)) then
            write(self%std_err_unit,"(' ')")
            write(self%std_err_unit,"(a,i4)") "Fortran error ",iostat
            inquire(unit=self%stdout_unit,opened=stdout_open)
            if (stdout_open) then
               if (self%std_err_unit/=self%stdout_unit) then
                  write(self%stdout_unit,"(' ')")
                  write(self%stdout_unit,"(a,i4)") "Fortran error ",iostat
               end if
            end if
         end if
      end if
      call flush_buffer_(self)
      self%warnings_issued = TRUE
   end subroutine

   subroutine warn_if(self,condition,message,iostat)
   ! If "condition" is true, issue a warning and continue, but set the error
   ! flag to -1 and
      type(SYSTEM_TYPE), INOUT :: self
      BIN, IN :: condition
      STR(len=*), IN :: message
      INT, IN, optional :: iostat
      if (condition) call warn_(self,message,iostat)
   end subroutine

   subroutine ensure(self,condition,message)
   ! Ensure "condition" is true, otherwise set the error flag to 1 and
   ! terminate the program with a "message"
      type(SYSTEM_TYPE), INOUT :: self
      BIN, IN :: condition
      STR(len=*), IN :: message
      if (NOT condition) call die_(self,message)
   end subroutine


!  ===========================================================
!  Unknown keywords: the preprocessor can define the "options"
!  ===========================================================

   subroutine unknown_0(self,word,name,options)
   ! Set the error flag to 1 and terminate the program with a message
   ! "Unknown option". The list of known keywords is dumped.
      type(SYSTEM_TYPE), INOUT :: self
      STR(len=*), IN :: word
      STR(len=*), IN :: name
      VEC(STR(len=*),:), IN :: options
      BIN :: stdout_open
      self%error_status = 1
      if (IO_is_allowed_(self)) then
         write(self%std_err_unit,*)
         write(self%std_err_unit,"(a)") "Error in "//trim(name)//" ... unknown option: "//trim(word)
         inquire(unit=self%stdout_unit,opened=stdout_open)
         if (stdout_open) then
            if (self%std_err_unit/=self%stdout_unit) then
               write(self%stdout_unit,*)
               write(self%stdout_unit,"(a)") "Error in "//trim(name)//" ... unknown option: "//trim(word)
            end if
         end if
      end if
      call report_io_file_info_(self)
      call report_keyword_info_(self,options)
#ifdef MPI
      ! Error path: abort all ranks rather than finalise this one. See die().
      if (self%is_parallel) then

         ! Say WHY, on THIS rank, before the job is killed.
         !
         ! Everything above is gated on .IO_is_allowed, i.e. master only -- so
         ! when a NON-master rank dies, which is the usual case for an MPI-only
         ! bug, the message was never written at all and the job died in total
         ! silence: nothing on stdout, nothing on stderr, nothing in <job>.err.
         ! That makes a parallel failure nearly undiagnosable, and it cost most
         ! of a day on the hart MPI_ERR_TRUNCATE hunt.
         !
         ! Written straight to Fortran's preconnected stderr (unit 0), not via
         ! TEXTFILE and not to .std_err_unit:
         !   . unit 0 exists on EVERY rank, whereas the std_err file is opened
         !     only on the master and its unit number is merely broadcast;
         !   . TEXTFILE:flush contains PARALLEL_BROADCASTs, so flushing here --
         !     from the one rank that is dying, while its peers run on -- would
         !     be a collective entered by a single rank, i.e. a hang. The error
         !     path must not use collectives.
         ! The rank is included because "which rank died" is the first question.
         write(0,'(a,i0,a)') "Error on rank ",self%processor_rank,": "//trim(name)//" ... unknown option: "//trim(word)
         flush(0)
         call MPI_ABORT(MPI_COMM_WORLD,self%error_status,self%mpi_error)
      end if
#endif

      ! Show the calls that led here
#ifdef DEBUG
#ifdef __GFORTRAN__
      call backtrace
#endif
#endif

      ! Non-zero: .error_status was set to 1 above, and a caller -- a shell,
      ! a CI job, scripts/test.py -- can only see that through the exit code.
      ! A bare "stop" exits 0, i.e. reports success while dying.
      stop 1
   end subroutine

   subroutine unknown_1(self,word,name)
   ! Set the error flag to 1 and terminate the program with a message
   ! "Unknown option". The list of known keywords is dumped.
      type(SYSTEM_TYPE), INOUT :: self
      STR(len=*), IN :: word
      STR(len=*), IN :: name
      BIN :: stdout_open
      self%error_status = 1
      if (IO_is_allowed_(self)) then
         write(self%std_err_unit,*)
         write(self%std_err_unit,"(a)") "Error in "//trim(name)//" ... unknown option: "//trim(word)
         inquire(unit=self%stdout_unit,opened=stdout_open)
         if (stdout_open) then
            if (self%std_err_unit/=self%stdout_unit) then
               write(self%stdout_unit,*)
               write(self%stdout_unit,"(a)") "Error in "//trim(name)//" ... unknown option: "//trim(word)
            end if
         end if
      end if
      call report_io_file_info_(self)
      if (allocated(self%known_keywords)) call report_keyword_info_(self,self%known_keywords)
#ifdef MPI
      ! Error path: abort all ranks rather than finalise this one. See die().
      if (self%is_parallel) then

         ! Say WHY, on THIS rank, before the job is killed.
         !
         ! Everything above is gated on .IO_is_allowed, i.e. master only -- so
         ! when a NON-master rank dies, which is the usual case for an MPI-only
         ! bug, the message was never written at all and the job died in total
         ! silence: nothing on stdout, nothing on stderr, nothing in <job>.err.
         ! That makes a parallel failure nearly undiagnosable, and it cost most
         ! of a day on the hart MPI_ERR_TRUNCATE hunt.
         !
         ! Written straight to Fortran's preconnected stderr (unit 0), not via
         ! TEXTFILE and not to .std_err_unit:
         !   . unit 0 exists on EVERY rank, whereas the std_err file is opened
         !     only on the master and its unit number is merely broadcast;
         !   . TEXTFILE:flush contains PARALLEL_BROADCASTs, so flushing here --
         !     from the one rank that is dying, while its peers run on -- would
         !     be a collective entered by a single rank, i.e. a hang. The error
         !     path must not use collectives.
         ! The rank is included because "which rank died" is the first question.
         write(0,'(a,i0,a)') "Error on rank ",self%processor_rank,": "//trim(name)//" ... unknown option: "//trim(word)
         flush(0)
         call MPI_ABORT(MPI_COMM_WORLD,self%error_status,self%mpi_error)
      end if
#endif

      ! Show the calls that led here
#ifdef DEBUG
#ifdef __GFORTRAN__
      call backtrace
#endif
#endif

      ! Non-zero: .error_status was set to 1 above, and a caller -- a shell,
      ! a CI job, scripts/test.py -- can only see that through the exit code.
      ! A bare "stop" exits 0, i.e. reports success while dying.
      stop 1
   end subroutine

   subroutine report_io_file_info(self)
   ! Report where the file being read had got to.
   !
   ! The values are copies held in SYSTEM, never read through a pointer to the
   ! file: a pointer here outlives its target, and Fortran neither nulls it nor
   ! lets ASSOCIATED detect that. See TASKS_AND_HISTORY.md.
      type(SYSTEM_TYPE), IN :: self
      STR(len=BSTR_SIZE) :: cursor
      INT :: item_end
      BIN :: stdout_open
      if (self%io_file_name==" ") return
      item_end = max(1,self%io_file_cursor)
      cursor = repeat("-",item_end-1)//"^"
      if (IO_is_allowed_(self)) then
         write(self%std_err_unit,*)
         write(self%std_err_unit,"('File name   = ',a)") trim(self%io_file_name)
         write(self%std_err_unit,"('Line number = ',i4)") self%io_file_record
         write(self%std_err_unit,"('File buffer = ',a)") trim(self%io_file_line)
         write(self%std_err_unit,"('Cursor -------',a)") trim(cursor)
         inquire(unit=self%stdout_unit,opened=stdout_open)
         if (stdout_open) then
            if (self%std_err_unit/=self%stdout_unit) then
               write(self%stdout_unit,*)
               write(self%stdout_unit,"('File name   = ',a)") trim(self%io_file_name)
               write(self%stdout_unit,"('Line number = ',i4)") self%io_file_record
               write(self%stdout_unit,"('File buffer = ',a)") trim(self%io_file_line)
               write(self%stdout_unit,"('Cursor -------',a)") trim(cursor)
            end if
         end if
      end if
      call flush_buffer_(self)
   end subroutine

   subroutine report_keyword_info(self,options)
   ! Report info about the most recent keywords used
      type(SYSTEM_TYPE), IN :: self
      VEC(STR(len=*),:), optional :: options
      INT :: n
      BIN :: stdout_open
      if (present(options)) then
         if (IO_is_allowed_(self)) then
            write(self%std_err_unit,*)
            write(self%std_err_unit,"('Allowed keyword options:')")
            write(self%std_err_unit,*)
            do n = 1,size(options)
               write(self%std_err_unit,"('   ',a)") trim(options(n))
            end do
            inquire(unit=self%stdout_unit,opened=stdout_open)
            if (stdout_open) then
               if (self%std_err_unit/=self%stdout_unit) then
                  write(self%stdout_unit,*)
                  write(self%stdout_unit,"('Allowed keyword options:')")
                  write(self%stdout_unit,*)
                  do n = 1,size(options)
                     write(self%stdout_unit,"('   ',a)") trim(options(n))
                  end do
               end if
            end if
         end if
      end if
      call flush_buffer_(self)
   end subroutine

   subroutine flush_buffer(self,unit)
   ! Flush the output
      type(SYSTEM_TYPE), IN :: self
      INT, optional, IN :: unit
      INT :: f_unit
      if (present(unit)) then; f_unit = unit
      else; f_unit = tonto%std_err_unit
      end if
      if (IO_is_allowed_(self)) then

#ifdef  FLUSH
!#ifndef MPI
         call flush(f_unit)
!#endif
#endif
      end if
   end subroutine


