   subroutine parallel_initialize(self)
   ! Initialise the parallel environment.
      type(SYSTEM_TYPE), INOUT :: self

#ifdef MPI

      ! The following code is inherited from PARALLEL
      self%is_parallel = TRUE
      self%parallel_do_lock = " "
      self%master_rank = 0
      call MPI_INIT(self%mpi_error)
      call MPI_COMM_DUP(MPI_COMM_WORLD,self%mpi_comm,self%mpi_error)
      call MPI_COMM_SIZE(self%mpi_comm,self%n_processors,self%mpi_error)
      call MPI_COMM_RANK(self%mpi_comm,self%processor_rank,self%mpi_error)
#else
      self%is_parallel = FALSE
      self%parallel_do_lock = " "
      self%master_rank = 0
      self%n_processors = 1
      self%processor_rank = 0
#endif
   end subroutine

   subroutine parallel_finalize(self)
   ! Finalise the parallel environment.
      type(SYSTEM_TYPE), INOUT :: self

      ! The following code is inherited from PARALLEL
      self%is_parallel = FALSE
#ifdef MPI
      call MPI_FINALIZE(self%mpi_error)
#endif
   end subroutine


