   NON_MPI_PURE subroutine parallel_symmetric_sum(self,mat)
   ! This routine adds the versions of "mat" from all processors, and gives the
   ! result to all processors. The matrix "mat" is assumed to be symmetric, and
   ! only the lower half of "mat" is summed; the upper triangle is forced to be
   ! the same as the lower triangle.
      type(SYSTEM_TYPE), INOUT :: self
      MAT(REAL,:,:), INOUT :: mat
      VEC(REAL,:), allocatable :: invec,outvec
      INT :: tri_size,dim
   ENSURE(self%is_parallel,"SYSTEM:parallel_symmetric_sum ... must be in a parallel environment")
   ENSURE(size(mat,1)==size(mat,2),"SYSTEM:parallel_symmetric_sum ... mat must be square")

      ! The following code is inherited from PARALLEL
      dim = size(mat,1)
      tri_size = dim*(dim+1)/2
      allocate(invec(tri_size))
      allocate(outvec(tri_size))
#ifdef MPI
      call compress_to_triangle_(self,invec,mat)
      call MPI_ALLREDUCE(invec,outvec,tri_size,MPI_DOUBLE_PRECISION,MPI_SUM,MPI_COMM_WORLD,self%mpi_error)
      call uncompress_from_triangle_(self,outvec,mat)
#endif
      deallocate(outvec)
      deallocate(invec)
   end subroutine

   NON_MPI_PURE subroutine parallel_symmetric_sum_23(self,mat)
   ! This routine sums together the lower half of the second
   ! two indices in all versions of "mat" on all processors,
   ! and gives the result back to all processors. The upper 
   ! triangle is forced to be the same as the lower triangle.
      type(SYSTEM_TYPE), INOUT :: self
      MAT3(REAL,:,:,:), INOUT :: mat
   ! It is the SECOND TWO indices that are symmetrised (see above), i.e. each
   ! mat(n,:,:) slice must be square -- not dim1 vs dim2. Callers pass
   ! MAT3{REAL}(n_states,n_bf,n_bf), so the old test asserted n_states==n_bf and
   ! fired spuriously in any USE_PRECONDITIONS build.
      VEC(REAL,:), allocatable :: invec,outvec
      INT :: tri_size,dim
      INT :: n
   ENSURE(self%is_parallel,"SYSTEM:parallel_symmetric_sum_23 ... must be in a parallel environment")
   ENSURE(size(mat,2)==size(mat,3),"SYSTEM:parallel_symmetric_sum_23 ... mat slices must be square")

      ! The following code is inherited from PARALLEL
      n = 0
      ! Must be dim2, not dim1: compress_to_triangle writes
      ! dim2*(dim2+1)/2 elements of the mat(n,:,:) slice below. Sizing the
      ! buffer from dim1 (= n_states) overflowed it by (n_bf^2 - n_states^2)/2
      ! doubles on every call, and MPI_ALLREDUCE then read past it too.
      dim = size(mat,2)
      tri_size = dim*(dim+1)/2
      allocate(invec(tri_size))
      allocate(outvec(tri_size))
#ifdef MPI
      do n = 1,size(mat,1)
         call compress_to_triangle_(self,invec,mat(n,:,:))
         call MPI_ALLREDUCE(invec,outvec,tri_size,MPI_DOUBLE_PRECISION,MPI_SUM,MPI_COMM_WORLD,self%mpi_error)
         call uncompress_from_triangle_(self,outvec,mat(n,:,:))
      end do
#endif
      deallocate(outvec)
      deallocate(invec)
   end subroutine

   PURE subroutine compress_to_triangle(self,tr,mat)
   ! Converts the lower triangle of matrix "mat" to the triangle "tr".
   ! using row order.
      type(SYSTEM_TYPE), INOUT :: self
      MAT(REAL,:,:), IN :: mat
      VEC(REAL,:), OUT :: tr
      INT :: ij,i,j
   ENSURE(size(mat,1)==size(mat,2),"SYSTEM:compress_to_triangle ... mat must be square")

      ! The following code is inherited from PARALLEL
      if (FALSE) self = self
      ij = 0
      do i = 1,size(mat,1)
         do j = 1,i
            tr(ij+j) = mat(i,j)
         end do
         ij = ij+i
      end do
   end subroutine

   PURE subroutine uncompress_from_triangle(self,tr,mat)
   ! Converts the triangle "tr" into the symmetric matrix "mat".
      type(SYSTEM_TYPE), INOUT :: self
      VEC(REAL,:), IN :: tr
      MAT(REAL,:,:), OUT :: mat
      REAL :: tmp
      INT :: ij,i,j
   ENSURE(size(mat,1)==size(mat,2),"SYSTEM:uncompress_from_triangle ... mat must be square")

      ! The following code is inherited from PARALLEL
      if (FALSE) self = self
      ij = 0
      do i = 1,size(mat,1)
         do j = 1,i
            tmp = tr(ij+j)
            mat(j,i) = tmp
            mat(i,j) = tmp
         end do
         ij = ij+i
      end do
   end subroutine


