      INT, INOUT :: val
      INT, OUT, optional :: min
      INT :: tmp
   ENSURE(self%is_parallel,"SYSTEM:scan_minimum_0 ... must be in a parallel enviornoment")

      ! The following code is inherited from PARALLEL
