   ENSURE(self%is_parallel,"SYSTEM:parallel_or_0 ... must be in a parallel environment")

#ifdef MPI

      ! The following code is inherited from PARALLEL
      call MPI_ALLREDUCE(bin,tmp,1,MPI_LOGICAL,MPI_LOR,MPI_COMM_WORLD,self%mpi_error)
      if (present(lor)) then
