! =======
! Barrier
! =======

   subroutine barrier(self)
   ! Blocks until all processes in the communicator have reached this routine.
      type(SYSTEM_TYPE), INOUT :: self
   ENSURE(self%is_parallel,"SYSTEM:barrier ... must be in a parallel environment")

#ifdef MPI

      ! The following code is inherited from PARALLEL
      call MPI_BARRIER(MPI_COMM_WORLD,self%mpi_error)
#else
      DIE("SYSTEM:barrier ... wtf?")
      self = self
#endif
   end subroutine

   subroutine ibarrier(self,request)
   ! Notifies the process that it has reached the barrier and returns immediately
      type(SYSTEM_TYPE), INOUT :: self
      INT, OUT, optional :: request
      INT :: req
   ENSURE(self%is_parallel,"SYSTEM:ibarrier ... must be in a parallel environment")

#ifdef MPI
#ifndef _WIN32

      ! The following code is inherited from PARALLEL
      call MPI_IBARRIER(MPI_COMM_WORLD,req,self%mpi_error)
      if (present(request)) request = req
#endif
#else
      req = 0
      if (present(request)) request = req
      DIE("SYSTEM:ibarrier ... wtf?")
      self = self
#endif
   end subroutine


! ====
! Wait
! ====

   subroutine parallel_wait(self,request)
   ! Waits for an MPI request to complete
      type(SYSTEM_TYPE) :: self
      INT, INOUT :: request

#ifdef MPI
      VEC(INT,6) :: status
   ENSURE(self%is_parallel,"SYSTEM:parallel_wait ... must be in a parallel environment")
#endif      

#ifdef MPI

      ! The following code is inherited from PARALLEL
      call MPI_WAIT(request,MPI_STATUS_IGNORE,self%mpi_error)
#else
      DIE("SYSTEM:parallel_wait ... wtf?")
      self = self
      request = request
#endif
   end subroutine

   subroutine waitall(self,array_of_requests)
   ! Waits for all given MPI Requests to complete
      type(SYSTEM_TYPE) :: self
      VEC(INT,:), INOUT :: array_of_requests

#ifdef MPI
      ! status :: VEC{INT}*
      INT :: i
      MAT(INT,:,:), allocatable :: statuses
   ENSURE(self%is_parallel,"SYSTEM:waitall ... must be in a parallel environment")

      ! The following code is inherited from PARALLEL
      ALLOCATE(statuses(size(array_of_requests),MPI_STATUS_SIZE))

#endif      

#ifdef MPI
      print *,size(array_of_requests)
      print *,array_of_requests
      print *,"Beginning wait"
      call MPI_WAITALL(size(array_of_requests),array_of_requests,statuses,self%mpi_error)
      print *,"Finished wait"
      DEALLOCATE(statuses)
#else
      array_of_requests(1) = 0
      DIE("SYSTEM:waitall ... wtf?")
      self = self
#endif
   end subroutine

   subroutine waitany(self,array_of_requests,index)
   ! Waits for any specified MPI Request to complete
      type(SYSTEM_TYPE) :: self
      VEC(INT,:), INOUT :: array_of_requests
      INT, OUT, optional :: index
#ifdef MPI
      INT :: indx
      VEC(INT,:), PTR :: status
   ENSURE(self%is_parallel,"SYSTEM:waitany ... must be in a parallel environment")

      ! The following code is inherited from PARALLEL
      ALLOCATE(status(MPI_STATUS_SIZE))
#endif      

#ifdef MPI
#ifndef _WIN32   
      call MPI_WAITANY(size(array_of_requests),array_of_requests,indx,status,self%mpi_error)
      if (present(index)) index = indx
      DEALLOCATE(status)
#endif
#else
      array_of_requests(1) = 0
      if (present(index)) index = 0
      DIE("SYSTEM:waitany ... wtf?")
      self = self
#endif
   end subroutine

   subroutine waitsome(self,array_of_requests,outcount,indices)
   ! Waits for some given MPI Requests to complete
      type(SYSTEM_TYPE) :: self
      VEC(INT,:), INOUT :: array_of_requests
      INT, OUT, optional :: outcount
      VEC(INT,:), OUT, optional :: indices

#ifdef MPI
      ! status :: VEC{INT}*
      INT :: i,ocount
      VEC(INT,:), allocatable :: ind
      MAT(INT,:,:), allocatable :: statuses
   ENSURE(self%is_parallel,"SYSTEM:waitsome ... must be in a parallel environment")

      ! The following code is inherited from PARALLEL
      ALLOCATE(statuses(size(array_of_requests),MPI_STATUS_SIZE))
      ALLOCATE(ind(size(array_of_requests)))

#endif      

#ifdef MPI
      call MPI_WAITSOME(size(array_of_requests),array_of_requests,ocount,ind,statuses,self%mpi_error)
      if (present(indices)) indices = ind
      if (present(outcount)) outcount = ocount
      DEALLOCATE(statuses)
#else
      array_of_requests(1) = outcount
      DIE("SYSTEM:waitsome ... wtf?")
      self = self
#endif
   end subroutine


