! Probe
! =====

   subroutine probe(self,source,tag)
   ! Blocking test for a message
      type(SYSTEM_TYPE) :: self
      INT, IN :: source
      INT, IN, optional :: tag
#ifdef MPI
      VEC(INT,MPI_STATUS_SIZE) :: status
#else
      VEC(INT,6) :: status
#endif
      INT :: mtag
   ENSURE(self%is_parallel,"SYSTEM:probe ... must be in a parallel environment")

      ! The following code is inherited from PARALLEL
      mtag = 1
      if (present(tag)) mtag = tag
#ifdef MPI
      call MPI_PROBE(source,mtag,MPI_COMM_WORLD,status,self%mpi_error)
#else
      status(1) = source
#endif
   end subroutine

   subroutine iprobe(self,source,tag,flag)
   ! Nonblocking test for a message
      type(SYSTEM_TYPE) :: self
      INT, IN :: source
      INT, IN, optional :: tag
      BIN, OUT :: flag
#ifdef MPI
      VEC(INT,MPI_STATUS_SIZE) :: status
#else
      VEC(INT,6) :: status
#endif
      INT :: mtag
   ENSURE(self%is_parallel,"SYSTEM:iprobe ... must be in a parallel environment")

      ! The following code is inherited from PARALLEL
      mtag = 1
      if (present(tag)) mtag = tag
#ifdef MPI
      call MPI_IPROBE(source,mtag,MPI_COMM_WORLD,flag,status,self%mpi_error)
#else
      flag = TRUE
      status(1) = source
#endif
   end subroutine


