   subroutine send_0(self,buf,dest,tag)
   ! Performs a blocking send
      type(SYSTEM_TYPE) :: self
      STR(len=*), INOUT :: buf
      INT, IN :: dest
      INT, IN, optional :: tag
      INT :: proc,mtag
   ENSURE(self%is_parallel,"SYSTEM:send_0 ... must be in a parallel environment")

      ! The following code is inherited from PARALLEL
      if (FALSE) self = self
      mtag = 1
      proc = dest

#ifdef MPI
      if (present(tag)) mtag = tag
      call MPI_SEND(buf,len(buf),MPI_CHARACTER,proc,mtag,MPI_COMM_WORLD,self%mpi_error)
#else
      DIE("SYSTEM:send_0 ... wtf?")
      proc = proc
      self = self
      mtag = mtag
      if (present(tag)) mtag = tag
      buf = buf
#endif
   end subroutine

