      INT, OUT, optional :: request
      INT :: req,proc,mtag
   ENSURE(self%is_parallel,"SYSTEM:isend_0 ... must be in a parallel environment")

      ! The following code is inherited from PARALLEL
      mtag = 1
      proc = dest

#ifdef MPI
      if (present(tag)) mtag = tag
      call MPI_ISEND(buf,len(buf),MPI_CHARACTER,proc,mtag,MPI_COMM_WORLD,req,self%mpi_error)
      if (present(request)) request = req
#else
      if (FALSE) self = self
      DIE("SYSTEM:isend_0 ... wtf?")
      proc = proc
      self = self
      req = 1
      buf = buf
      if (present(tag)) mtag = tag
      if (present(request)) request = req
#endif
   end subroutine

