! =============
! Window p_loop
! =============

   subroutine setup_p_loop(self,w,lb,ub)
   ! Set up locks and windows, return actual window index "w"
      type(SYSTEM_TYPE), INOUT :: self
      INT, OUT :: w
      INT, optional, IN :: lb,ub

      ! Lock inner loops

      ! The following code is inherited from PARALLEL
      call lock_parallel_do_(self,"no")

      ! Set loop bounds
      self%p_loop_lbound = lb
      self%p_loop_ubound = ub

      ! Initialize start
      self%p_loop_index = lb
      call win_create_(self,self%p_loop_index,1,0,w)
   end subroutine

   pure function exit_p_loop(self) result (res)
   ! Return whether the p_loop should exit; this happens by
   ! convention if the loop index is set below its allowed
   ! lower bound.
      type(SYSTEM_TYPE), IN :: self
      BIN :: res

      ! The following code is inherited from PARALLEL
      res = self%p_loop_index>self%p_loop_ubound OR self%p_loop_index<self%p_loop_lbound
   end function

   function next_p_loop_index(self,w) result (g)
   ! Return the next loop index in a parallel loop for window "w".
      type(SYSTEM_TYPE), INOUT :: self
      INT, INOUT :: w
      INT :: g
      INT :: x

      ! The following code is inherited from PARALLEL
      x = 1

      ! Master has last say over window "w"
      ! This is a barrier to the first other than master.
      call win_lock_exclusive_(self,self%master_rank,w)
      if (NOT is_master_processor_(self)) then
         call get_accumulate_sum_(self,x,self%p_loop_index,self%master_rank,0,w)
      end if

      ! Release window "w" for next processor.
      call win_unlock_(self,self%master_rank,w)

      ! Master and salve get the same "g"
      g = self%p_loop_list(self%p_loop_index)
   end function


