      INT :: d,i,w
   ENSURE(self%is_parallel,"SYSTEM:win_allocate_shared ... must be in a parallel enviornoment")

#ifdef MPI

      ! The following code is inherited from PARALLEL
      d = 0
      i = 0
      if (present(siz)) then
         s = siz
      else
         s = 0
      end if
      if (present(disp_unit)) d = disp_unit
      if (present(info)) i = info
      call MPI_WIN_ALLOCATE_SHARED(s,d,i,MPI_COMM_WORLD,base,w,self%mpi_error)
      if (present(win)) win = w
#else
      w = 0
      if (w==1) print *,base
      if (present(siz)) s = siz
      if (present(disp_unit)) d = disp_unit
      if (present(info)) i = info
      if (present(win)) win = w
      if (FALSE) self = self
      DIE("SYSTEM:win_allocate_shared ... wtf?")
#endif
   end subroutine


