#endif
   end subroutine


! ==================
! Window Lock/Unlock
! ==================

   subroutine win_lock_exclusive(self,rank,win)
   ! Begin an RMA access epoch at the target process. 
      type(SYSTEM_TYPE), INOUT :: self
      INT, INOUT :: rank
      INT, INOUT :: win
   ENSURE(self%is_parallel,"SYSTEM:win_lock_exclusive ... must be in a parallel environment")

#ifdef MPI
#ifndef _WIN32

      ! The following code is inherited from PARALLEL
      call MPI_WIN_LOCK(MPI_LOCK_EXCLUSIVE,rank,0,win,self%mpi_error)
#endif
#else
      DIE("SYSTEM:win_lock_exclusive ... wtf?")
      rank = rank
      win = win
      self = self
#endif
   end subroutine

   subroutine win_lock_shared(self,rank,win)
   ! Begin an RMA access epoch at the target process. 
      type(SYSTEM_TYPE), INOUT :: self
      INT, INOUT :: rank
      INT, INOUT :: win
   ENSURE(self%is_parallel,"SYSTEM:win_lock_shared ... must be in a parallel environment")

#ifdef MPI
#ifndef _WIN32

      ! The following code is inherited from PARALLEL
      call MPI_WIN_LOCK(MPI_LOCK_SHARED,rank,0,win,self%mpi_error)
#endif
#else
      DIE_IF(win==rank,"SYSTEM:win_lock_shared ... wtf?")
      rank = rank
      win = win
      self = self
#endif
   end subroutine

   subroutine win_unlock(self,rank,win)
   ! Completes an RMA access epoch at the target process. 
      type(SYSTEM_TYPE), INOUT :: self
      INT, INOUT :: rank
      INT, INOUT :: win
   ENSURE(self%is_parallel,"SYSTEM:win_unlock ... must be in a parallel environment")

#ifdef MPI

      ! The following code is inherited from PARALLEL
      call MPI_WIN_UNLOCK(rank,win,self%mpi_error)
#else
      DIE_IF(win==rank,"SYSTEM:win_unlock ... wtf?")
      rank = rank
      win = win
      self = self
#endif
   end subroutine


