   function IO_is_allowed(self) result (res)
   ! Return whether or not this processor is allowed to do the I/O operation.
   ! Here, only the master processor does I/O in a parallel job.
      type(SYSTEM_TYPE), IN :: self
      BIN :: res
      if (self%per_rank_IO_allowed) then
         res = TRUE
      else
         res = is_master_processor_(self) OR (NOT self%is_parallel)
      end if
   end function


! ===========================================
! These are all inherited from SYSTEM_COMMAND
! ===========================================
! Shell command execution. As with PARALLEL, inheritance is text inclusion, so
! there is no fortran dependency between SYSTEM and SYSTEM_COMMAND. Usage:
!
!    tonto.set_command("gnuplot urea.gnuplot")
!    tonto.execute_command
!    if (tonto.command_failed) tonto.put_command_info
!
! WARNING (parallel builds): .execute_command is NOT collective -- it runs the
! command on whichever rank reaches it. Guard it with .is_master_processor, or
! every rank spawns its own copy. See the header of system_command.foo.

   PURE subroutine set_command_defaults(self)
   ! Set up the default command settings.
      type(SYSTEM_TYPE), INOUT :: self

      ! The following code is inherited from SYSTEM_COMMAND
      self%command = " "
      self%command_wait = TRUE
      self%command_exit_status = 0
      self%command_status = 0
      self%command_message = " "
   end subroutine

   PURE subroutine set_command(self,val)
   ! Set the shell command "val" to be executed, and clear any previous result.
      type(SYSTEM_TYPE), INOUT :: self
      STR(len=*), IN :: val
   ENSURE(val/=" ","SYSTEM:set_command ... empty command!")

      ! The following code is inherited from SYSTEM_COMMAND
      self%command = val
      self%command_exit_status = 0
      self%command_status = 0
      self%command_message = " "
   end subroutine

   pure subroutine set_command_wait(self,val)
   ! Set whether to wait for the command to complete.
      type(SYSTEM_TYPE), INOUT :: self
      BIN, IN :: val

      ! The following code is inherited from SYSTEM_COMMAND
      self%command_wait = val
   end subroutine

   pure subroutine set_command_asynchronous(self)
   ! Run the command in the background i.e. do not wait for it to finish.
      type(SYSTEM_TYPE), INOUT :: self

      ! The following code is inherited from SYSTEM_COMMAND
      self%command_wait = FALSE
   end subroutine

   pure subroutine set_command_synchronous(self)
   ! Wait for the command to finish before continuing. This is the default.
      type(SYSTEM_TYPE), INOUT :: self

      ! The following code is inherited from SYSTEM_COMMAND
      self%command_wait = TRUE
   end subroutine

   subroutine execute_command(self)
   ! Execute ".command" in a shell, recording the exit status, the command
   ! status, and any message.
      type(SYSTEM_TYPE), INOUT :: self
   ENSURE(self%command/=" ","SYSTEM:execute_command ... empty command!")

      ! The following code is inherited from SYSTEM_COMMAND
      call execute_command_line(self%command,self%command_wait,self%command_exit_status,self%command_status,self%command_message)
   end subroutine

   subroutine execute(self,val)
   ! Convenience: set the command "val" and execute it in one call.
      type(SYSTEM_TYPE), INOUT :: self
      STR(len=*), IN :: val
   ENSURE(val/=" ","SYSTEM:execute ... empty command!")

      ! The following code is inherited from SYSTEM_COMMAND
      call set_command_(self,val)
      call execute_command_(self)
   end subroutine

   subroutine call_gnuplot(self,script,image)
   ! Render the gnuplot input file "script" into the PNG "image" by running
   ! gnuplot. Master rank only; a missing gnuplot warns rather than dies.
      type(SYSTEM_TYPE), INOUT :: self
      STR(len=*), IN :: script,image
      STR(len=STR_SIZE) :: cmd
      BIN :: failed

      ! The following code is inherited from SYSTEM_COMMAND
      if (NOT is_master_processor_(self)) return
      cmd = "gnuplot -e 'set terminal pngcairo size 900,900'"
      cmd = trim(cmd)//" '"//trim(script)//"'"
      cmd = trim(cmd)//" > '"//trim(image)//"' 2>/dev/null"
      call execute_(self,trim(cmd))

      ! Taken before the cleanup below, which runs a command of its own and so
      ! overwrites what .command_failed reports.
      failed = command_failed_(self)
      if (failed) then

         ! The shell creates the redirection target before it even looks for
         ! gnuplot, so a run that failed leaves a zero-byte PNG behind. Remove
         ! it: an empty picture file is worse than no picture at all, because
         ! it looks like a plot that was drawn.
         call execute_(self,"rm -f '"//trim(image)//"'")
         if (IO_is_allowed_(self)) then
            write(self%stdout_unit,*)
            write(self%stdout_unit,"(a)") "WARNING: could not run gnuplot, so no "//trim(image)//" was made."
            write(self%stdout_unit,"(a)") "Is gnuplot installed and on your PATH? The plot data and the"
            write(self%stdout_unit,"(a)") "gnuplot script were written anyway, so you can do it yourself:"
            write(self%stdout_unit,*)
            write(self%stdout_unit,"(a)") "   gnuplot -persist '"//trim(script)//"'"
            write(self%stdout_unit,*)
         end if
      end if
   end subroutine

   function command_failed(self) result (res)
   ! Return TRUE if the last synchronous command could not be run, or ran and
   ! returned a non-zero exit status.
      type(SYSTEM_TYPE), IN :: self
      BIN :: res

      ! The following code is inherited from SYSTEM_COMMAND
      if (NOT self%command_wait) then
         res = FALSE
      else
         res = self%command_status/=0 OR self%command_exit_status/=0
      end if
   end function

   subroutine put_command_info(self)
   ! Put out the command and the result of executing it.
      type(SYSTEM_TYPE), IN :: self

      ! The following code is inherited from SYSTEM_COMMAND
      if (NOT IO_is_allowed_(self)) return
      write(self%stdout_unit,*)
      write(self%stdout_unit,"(a)") "======================"
      write(self%stdout_unit,"(a)") "Execute system command"
      write(self%stdout_unit,"(a)") "======================"
      write(self%stdout_unit,*)
      write(self%stdout_unit,"(a)") "Command                      = "//trim(self%command)
      write(self%stdout_unit,"(a,l1)") "Wait for it to finish?       = ",self%command_wait
      write(self%stdout_unit,"(a,i0)") "Exit status (sys. dependent) = ",self%command_exit_status
      write(self%stdout_unit,"(a,i0)") "Command status               = ",self%command_status
      write(self%stdout_unit,"(a)") "Command message              = "//trim(self%command_message)
   end subroutine

end module
